 private static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
 private static ServerPlayer fake(ServerLevel level,String name){return net.neoforged.neoforge.common.util.FakePlayerFactory.get(level,new com.mojang.authlib.GameProfile(java.util.UUID.randomUUID(),name));}
 private static void learn(ServerPlayer player,String id){
  var b=CoreRuntime.balance;var a=b.abilities.stream().filter(n->n.id().equals(id)).findFirst().orElseThrow();var p=CoreRuntime.data(player);if(p.unlocked.contains(id))return;
  for(String parent:a.all())learn(player,parent);for(var r:a.skillRequirements())p.track(r.skill()).level=Math.max(p.track(r.skill()).level,r.level());for(var c:a.actionConditions())p.setCounter(c.counter(),c.amount(),b);
  player.getServer().getCommands().performPrefixedCommand(player.createCommandSourceStack(),"essence unlock "+id);check(p.unlocked.contains(id),"Essence command really learns "+id);
 }
 private static net.neoforged.neoforge.network.handling.IPayloadContext context(ServerPlayer player){return (net.neoforged.neoforge.network.handling.IPayloadContext)java.lang.reflect.Proxy.newProxyInstance(WeaponMasteryRuntime.class.getClassLoader(),new Class[]{net.neoforged.neoforge.network.handling.IPayloadContext.class},(proxy,method,args)->{if(method.getName().equals("player"))return player;if(method.getName().equals("enqueueWork")){((Runnable)args[0]).run();return java.util.concurrent.CompletableFuture.completedFuture(null);}return null;});}
