  for(String guardName:java.util.List.of("guard","parrying","impact_guard")){
   var guard=(yesman.epicfight.skill.guard.GuardSkill)yesman.epicfight.registry.EpicFightRegistries.SKILL.get(ResourceLocation.parse("epicfight:"+guardName));defenderGuard.setSkill(guard);CoreRuntime.data(clone).stamina=20;CoreRuntime.data(clone).exhausted=false;var hit=new yesman.epicfight.api.event.types.entity.TakeDamageEvent.Income(copied,source,5);guard.guard(defenderGuard,defenderCap,copied,hit,0,3,false);check(hit.isCanceled()==guardName.equals("impact_guard"),"innate bypasses only non-enhanced guard "+guardName);
  }
  var ordinary=new yesman.epicfight.world.damagesource.EpicFightDamageSource(player.damageSources().playerAttack(player)).setUsedItem(player.getMainHandItem()).setBaseImpact(3);var baseGuard=(yesman.epicfight.skill.guard.GuardSkill)yesman.epicfight.registry.EpicFightRegistries.SKILL.get(ResourceLocation.parse("epicfight:guard"));defenderGuard.setSkill(baseGuard);var defendData=CoreRuntime.data(clone);
  defenderGuard.getDataManager().setData(yesman.epicfight.registry.entries.EpicFightSkillDataKeys.PENALTY,0.0F);defendData.stamina=20;defendData.exhausted=false;p.disabled.add(great.id());baseGuard.guard(defenderGuard,defenderCap,copied,new yesman.epicfight.api.event.types.entity.TakeDamageEvent.Income(copied,ordinary,5),0,3,false);double normalCost=20-defendData.stamina;
  defenderGuard.getDataManager().setData(yesman.epicfight.registry.entries.EpicFightSkillDataKeys.PENALTY,0.0F);defendData.stamina=20;defendData.exhausted=false;p.disabled.remove(great.id());baseGuard.guard(defenderGuard,defenderCap,copied,new yesman.epicfight.api.event.types.entity.TakeDamageEvent.Income(copied,ordinary,5),0,3,false);check(normalCost>0&&Math.abs((20-defendData.stamina)-2*normalCost)<0.001,"ordinary greatsword pressure on guards doubled exactly once");
  var defense=b.trees.stream().filter(t->t.skill()==com.faust.core.progression.Skill.defense).findFirst().orElseThrow().nodes();var parryNode=defense.stream().filter(n->n.ability().endsWith("/parrying")).findFirst().orElseThrow();var longNode=defense.stream().filter(n->n.ability().equals(WeaponMastery.LONG)).findFirst().orElseThrow();var shieldNode=defense.stream().filter(n->n.ability().equals(Combat.SHIELD_MASTERY)).findFirst().orElseThrow();var guardNode=defense.stream().filter(n->n.ability().endsWith("/guard")).findFirst().orElseThrow();var ironNode=defense.stream().filter(n->n.ability().equals("faustcore:training_defense_armor")).findFirst().orElseThrow();check(longNode.x()==parryNode.x()&&longNode.y()==shieldNode.y()&&guardNode.y()==ironNode.y(),"defense rows and longsword mastery position");
  var strength=b.trees.stream().filter(t->t.skill()==com.faust.core.progression.Skill.strength).findFirst().orElseThrow().nodes();var greatNode=strength.stream().filter(n->n.ability().equals(WeaponMastery.GREAT)).findFirst().orElseThrow();var gripNode=strength.stream().filter(n->n.ability().equals(Combat.MASTERY)).findFirst().orElseThrow();var pairNode=strength.stream().filter(n->n.ability().equals(Combat.SWORD_MASTERY)).findFirst().orElseThrow();check(greatNode.x()==pairNode.x()&&greatNode.y()==gripNode.y(),"greatsword mastery row and column");
  p.unlocked.remove(great.id());p.setCounter(WeaponMastery.SWINGS,0,b);yesman.epicfight.gameasset.Animations.GREATSWORD_AUTO1.get().begin(patch);check(p.conditionCount(great,great.actionConditions().getFirst())==1,"real greatsword animation records swing");p.setCounter(WeaponMastery.SWINGS,100,b);p.unlock(great.id(),b);
